    private static function pending_selector($token) {
        $pending = get_transient('tisa_update_' . $token);
        if (!is_array($pending) || (int)($pending['owner'] ?? 0) !== get_current_user_id()) { echo '<div class="notice notice-error"><p>اطلاعات شارژ منقضی شده است؛ ZIP را دوباره آپلود کنید.</p></div>'; return; }
        $data = $pending['data'];
        echo '<h2>انتخاب محصول برای شارژ</h2><p>محصول مناسب را انتخاب کنید. اگر در نتایج نبود، عنوان یا SKU را جستجو کنید.</p>';
        echo '<input id="tisa-product-search" type="search" class="regular-text" placeholder="جستجوی عنوان یا SKU..."> <button id="tisa-search-btn" class="button">جستجو</button>';
        echo '<div id="tisa-results" style="margin-top:16px;max-width:820px"></div>';
        echo '<button id="tisa-apply-update" class="button button-primary" disabled>اعمال شارژ روی محصول انتخاب‌شده</button>';
        echo '<p id="tisa-update-status"></p>';
        $ajax = admin_url('admin-ajax.php');
        $apply = admin_url('admin-post.php');
        $nonce = wp_create_nonce('tisa_update_' . $token);
        echo '<script>(function(){const q=document.getElementById("tisa-product-search"),r=document.getElementById("tisa-results"),b=document.getElementById("tisa-apply-update"),s=document.getElementById("tisa-update-status");let selected=0,snapshot="";q.value=' . wp_json_encode($data['title'] ?? '') . ';function search(){s.textContent="🔎 در حال جستجوی واقعی محصولات...";fetch(' . wp_json_encode($ajax) . '+"?action=tisa_search_existing_products&nonce="+' . wp_json_encode(wp_create_nonce('tisa_search_products')) . '+"&pending="+' . wp_json_encode($token) . '+"&q="+encodeURIComponent(q.value)).then(x=>x.json()).then(j=>{r.innerHTML="";selected=0;b.disabled=true;(j.data||[]).forEach(p=>{const row=document.createElement("label");row.style="display:block;border:1px solid #dcdcde;background:#fff;padding:12px;margin:6px 0;cursor:pointer";row.innerHTML=(p.image?"<img src=\""+p.image+"\" style=\"width:72px;height:72px;object-fit:cover;vertical-align:middle;margin-left:12px;border-radius:6px\">":"<span style=\"display:inline-block;width:72px;height:72px;vertical-align:middle;margin-left:12px;background:#f0f0f1;text-align:center;padding-top:24px;box-sizing:border-box\">بدون عکس</span>")+"<input type=radio name=tisa_product value="+p.id+"> <strong>"+p.title+"</strong> — SKU: "+(p.sku||"-")+" — قیمت فعلی: "+(p.price||"-")+" — ID: "+p.id+"<br><small>ویژگی‌های فعلی: "+((p.attributes||[]).join(" | ")||"-")+"</small>";row.querySelector("input").onchange=()=>{selected=p.id;snapshot=p.snapshot;b.disabled=false};r.appendChild(row)});s.textContent=j.data&&j.data.length?"✅ محصول موردنظر را انتخاب کنید.":"محصولی پیدا نشد؛ عبارت دیگری جستجو کنید."}).catch(()=>s.textContent="❌ خطا در جستجو")};document.getElementById("tisa-search-btn").onclick=search;q.onkeydown=e=>{if(e.key==="Enter")search()};if(q.value)search();b.onclick=()=>{if(!selected)return;s.textContent="⚙️ در حال اعمال امن تغییرات و حفظ اطلاعات واریژن‌های مشترک...";const f=new FormData();f.append("action","tisa_apply_update");f.append("_wpnonce",' . wp_json_encode($nonce) . ');f.append("token",' . wp_json_encode($token) . ');f.append("product_id",selected);f.append("snapshot",snapshot);fetch(' . wp_json_encode($apply) . ',{method:"POST",body:f}).then(x=>{window.location.href=x.url})}})();</script>';
    }

    private static function fail($message) {
        wp_safe_redirect(add_query_arg(['page'=>'tisa-product-importer','tisa_type'=>'error','tisa_notice'=>rawurlencode($message)], admin_url('admin.php')));
        exit;
    }

    private static function success($message, $product_id = 0) {
        $args = ['page'=>'tisa-product-importer','tisa_type'=>'success','tisa_notice'=>$message];
        if ($product_id) $args['tisa_product_id'] = (int)$product_id;
        wp_safe_redirect(add_query_arg($args, admin_url('admin.php')));
        exit;
    }

    public static function import() {
        if (!current_user_can('manage_woocommerce')) wp_die('دسترسی غیرمجاز');
        check_admin_referer(self::NONCE);
        if (!class_exists('WooCommerce')) self::fail('ووکامرس فعال نیست');
        $stage = null; $images = []; $active = null;
        try {
            $file = $_FILES['product_zip'] ?? null;
            if (!$file || $file['error'] !== UPLOAD_ERR_OK || strtolower(pathinfo($file['name'], PATHINFO_EXTENSION)) !== 'zip') throw new RuntimeException('فایل ZIP معتبر دریافت نشد');
            $stage = Tisa_Zip_Reader::read($file['tmp_name']);
            $data = $stage['data'];
            $batch = isset($data['batch_id']) && preg_match('/^[a-zA-Z0-9_-]{1,64}$/D', $data['batch_id']) ? $data['batch_id'] : 'zip_' . substr(hash_file('sha256', $file['tmp_name']), 0, 24);
            if (($data['mode'] ?? 'new') === 'update') {
                $token = bin2hex(random_bytes(16));
                if (!set_transient('tisa_update_' . $token, $stage + ['owner'=>get_current_user_id()], HOUR_IN_SECONDS)) throw new RuntimeException('ثبت درخواست شارژ ناموفق بود');
                wp_safe_redirect(add_query_arg(['page'=>'tisa-product-importer', 'tisa_pending'=>$token], admin_url('admin.php')));
                exit;
            }
            $active = fopen($stage['dir'] . '/.active', 'c');
            if (!$active || !flock($active, LOCK_EX | LOCK_NB)) throw new RuntimeException('این بسته در حال پردازش است');
            if (!Tisa_REST_Fencing::lock('batch:' . $batch)) throw new RuntimeException('قفل انتشار در دسترس نیست');
            $id = Tisa_REST_Fencing::find_batch($batch);
            if ($id) {
                if (get_post_status($id) === 'trash') throw new RuntimeException('این بسته را در سایت حذف کرده‌اید؛ برای ساخت تازه از ربات تأیید تازه بگیرید');
            } else {
                Tisa_Product_Operations::combinations(Tisa_Product_Operations::axes($data), $data);
                $images = Tisa_Zip_Reader::upload($stage['images']);
                $id = Tisa_Product_Operations::create($data, $images, $batch);
            }
            if ($active) { fclose($active); $active = null; }
            Tisa_Zip_Reader::remove($stage['dir']); $stage = null;
            self::success('محصول با موفقیت ساخته شد (بستهٔ تکراری دوباره ساخته نمی‌شود).', $id);
        } catch (Throwable $error) {
            if ($active) fclose($active);
            Tisa_Zip_Reader::rollback_uploads($images);
            if ($stage) Tisa_Zip_Reader::remove($stage['dir']);
            error_log('[Tisa Product Importer] ' . $error->getMessage());
            self::fail('ساخت محصول ناموفق بود: ' . $error->getMessage());
        }
    }

    public static function search_existing_products() {
        if (!current_user_can('manage_woocommerce') || !wp_verify_nonce($_GET['nonce'] ?? '', 'tisa_search_products')) wp_send_json_error('دسترسی غیرمجاز', 403);
        $q = sanitize_text_field(wp_unslash($_GET['q'] ?? ''));
        $args = ['post_type'=>'product', 'post_status'=>['publish','draft','pending','private'], 'posts_per_page'=>30, 's'=> $q, 'orderby'=>'relevance'];
        $query = new WP_Query($args);
        $items = [];
        foreach ($query->posts as $post) {
            $items[] = self::candidate_data($post->ID);
        }
        if ($q !== '') {
            global $wpdb;
            $ids = $wpdb->get_col($wpdb->prepare("SELECT post_id FROM {$wpdb->postmeta} WHERE meta_key='_sku' AND meta_value LIKE %s LIMIT 30", '%' . $wpdb->esc_like($q) . '%'));
            foreach ($ids as $id) { $post=get_post($id); if ($post && $post->post_type==='product') $items[] = self::candidate_data($post->ID); }
        }
        $unique=[]; foreach ($items as $item) $unique[$item['id']]=$item;
        wp_send_json_success(array_values($unique));
    }

    private static function candidate_data($product_id) {
        $product = function_exists('wc_get_product') ? wc_get_product($product_id) : null;
        $attributes = [];
        if ($product) foreach ($product->get_attributes() as $attribute) $attributes[] = esc_html($attribute->get_name()) . ': ' . esc_html(implode(' | ', $attribute->get_options()));
        return ['snapshot'=>Tisa_Product_Operations::snapshot($product_id), 'id'=>$product_id, 'title'=>esc_html(get_the_title($product_id)), 'sku'=>esc_html((string)get_post_meta($product_id, '_sku', true)), 'price'=>$product ? esc_html($product->get_price()) : '', 'attributes'=>$attributes, 'image'=>esc_url(get_the_post_thumbnail_url($product_id, 'thumbnail') ?: '')];
    }

    public static function apply_update() {
        if (!current_user_can('manage_woocommerce')) wp_die('دسترسی غیرمجاز');
        $token = sanitize_text_field(wp_unslash($_POST['token'] ?? ''));
        check_admin_referer('tisa_update_' . $token);
        $pending = get_transient('tisa_update_' . $token);
        $id = absint($_POST['product_id'] ?? 0); $images = []; $active = null;
        if (!is_array($pending) || (int)($pending['owner'] ?? 0) !== get_current_user_id() || !$id || !current_user_can('edit_post', $id)) self::fail('درخواست شارژ/مالک/دسترسی محصول معتبر نیست');
        try {
            $active = fopen($pending['dir'] . '/.active', 'c');
            if (!$active || !flock($active, LOCK_EX | LOCK_NB)) throw new RuntimeException('این بسته همین الان در حال پردازش است');
            if (($pending['data']['image_mode'] ?? 'replace') === 'replace') $images = Tisa_Zip_Reader::upload($pending['images']);
            Tisa_Product_Operations::update($id, $pending['data'], $images, sanitize_text_field(wp_unslash($_POST['snapshot'] ?? '')));
            fclose($active); $active = null;
            delete_transient('tisa_update_' . $token); Tisa_Zip_Reader::remove($pending['dir']);
            self::success('شارژ با حفظ ID و اطلاعات ترکیب‌های مشترک انجام شد.', $id);
        } catch (Throwable $error) {
            if ($active) fclose($active);
            Tisa_Zip_Reader::rollback_uploads($images);
            delete_transient('tisa_update_' . $token); Tisa_Zip_Reader::remove($pending['dir']);
            error_log('[Tisa Product Importer update] ' . $error->getMessage());
            self::fail('شارژ محصول ناموفق بود: ' . $error->getMessage());
        }
    }

    private static function filter_combos($combos, $restrictions) {
        if (!$combos || !is_array($restrictions) || !$restrictions) return $combos;
        $allowed = [];
        foreach ($restrictions as $model => $colors) {
            if (!is_array($colors) || !$colors) continue;
            $key = self::model_key($model);
            if ($key === '') continue;
            foreach ($colors as $color) {
                $color = self::color_key($color);
                if ($color !== '') $allowed[$key][$color] = true;
            }
        }
        if (!$allowed) return $combos;
        $model_keys = []; $color_keys = [];
        foreach (array_keys((array)$combos[0]) as $name) {
            if (self::is_model_attr($name)) $model_keys[] = $name;
            elseif (self::is_color_attr($name)) $color_keys[] = $name;
        }
        if (!$model_keys || !$color_keys) return $combos;
        // Colors that really exist on the attribute axis. A restriction that
        // matches none of them is a spelling mismatch, not an empty stock list,
        // so that model stays unrestricted instead of losing every variation.
        $available = [];
        foreach ($combos as $combo) foreach ($color_keys as $name) $available[self::color_key($combo[$name])] = true;
        $out = [];
        foreach ($combos as $combo) {
            $keep = true;
            foreach ($model_keys as $name) {
                $key = self::model_key($combo[$name]);
                if (!isset($allowed[$key])) continue;
                $usable = array_intersect_key($allowed[$key], $available);
                if (!$usable) continue;
                foreach ($color_keys as $color_name) {
                    if (!isset($usable[self::color_key($combo[$color_name])])) { $keep = false; break; }
                }
                if (!$keep) break;
            }
            if ($keep) $out[] = $combo;
        }
        return $out ? $out : $combos;
    }

    private static function recursive_images($dir) {
        $out = []; $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir, FilesystemIterator::SKIP_DOTS));
        foreach ($it as $f) if (preg_match('/\.(jpe?g|png|webp)$/i', $f->getFilename())) $out[] = $f->getPathname();
        return $out;
    }

}
Tisa_Product_Zip_Importer::init();
